const anzahl = Number($('⚙️ Vergleich-Einstellungen').first().json.anzahl || 20);
return $input
  .all()
  .filter((i) => i.json.cache_id)
  .slice(0, anzahl)
  .map((i) => ({ json: { id: i.json.id, url: i.json.url, cache_id: i.json.cache_id } }));

const row = $('Schleife: eine Stelle nach der anderen').first().json;
const cache = $('Seitentext aus Cache').first().json;

const vorlage = String($json.text || '').split('\n').filter((z) => !/^#(?!#)/.test(z)) /* '# …' = Kommentar, '## …' = Überschrift bleibt */.join('\n');
const [system, anfrage] = vorlage.split('=== ANFRAGE ===').map((t) => t.trim());
const fuellen = (t, werte) => t.replace(/\{\{(\w+)\}\}/g, (m, k) => (k in werte ? werte[k] : m));

// Gleiches Schema wie in "02 Stelle verarbeiten" → "Extraktions-Anfrage bauen"
const text = (beschreibung) => ({ type: 'string', description: beschreibung });
const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['seitentyp', 'status', 'datum_zitat', 'veroeffentlichungsdatum', 'jobtitel', 'firma', 'ort', 'remote', 'remote_regel_wortlaut', 'gehalt', 'vertragsform', 'bewerbungsweg', 'kurze_zusammenfassung', 'begruendung'],
  properties: {
    seitentyp: { type: 'string', enum: ['einzelne_stelle', 'stellenliste', 'keine_stelle'] },
    status: { type: 'string', enum: ['aktiv', 'abgelaufen', 'unklar'] },
    datum_zitat: text('Wörtliche Textstelle mit dem Veröffentlichungsdatum oder leer'),
    veroeffentlichungsdatum: text('YYYY-MM-DD oder leer'),
    jobtitel: text('Jobtitel'),
    firma: text('Firmenname'),
    ort: text('Ort/Land'),
    remote: { type: 'string', enum: ['ja', 'nein', 'hybrid', 'unklar'] },
    remote_regel_wortlaut: text('Wörtliches Zitat zur Remote-Regel'),
    gehalt: text('Gehalt/Stundensatz wie angegeben'),
    vertragsform: text('z. B. Festanstellung, Freelance, EOR'),
    bewerbungsweg: text('z. B. Formular, E-Mail'),
    kurze_zusammenfassung: text('2–3 Sätze'),
    begruendung: text('1–2 Sätze zu status und seitentyp'),
  },
};

const basis = {
  system,
  anfrage: fuellen(anfrage, { HEUTE: $now.toFormat('yyyy-MM-dd'), URL: row.url, TITEL: cache.title || '', SEITENTEXT: '{{SEITENTEXT}}' }),
  seitentext: cache.text || '',
  schema: SCHEMA,
  kontext: { id: row.id, url: row.url, cache_id: row.cache_id },
};
// Zwei Items = zwei Aufrufe von "00 KI-Aufruf", einmal pro Modell
return [{ json: { ...basis, anbieter_override: 'claude' } }, { json: { ...basis, anbieter_override: 'ollama' } }];

const alle = $input.all().map((i) => i.json);
const c = alle.find((x) => x.anbieter === 'claude') || {};
const o = alle.find((x) => x.anbieter === 'ollama') || {};
const kontext = c.kontext || o.kontext || {};
const dc = c.daten || {};
const dO = o.daten || {};
const FELDER = {
  seitentyp: 'seitentyp',
  status: 'status',
  datum: 'veroeffentlichungsdatum',
  jobtitel: 'jobtitel',
  firma: 'firma',
  remote: 'remote',
  remote_regel: 'remote_regel_wortlaut',
  gehalt: 'gehalt',
  vertragsform: 'vertragsform',
  zusammenfassung: 'kurze_zusammenfassung',
};
const out = { url: kontext.url, cache_id: kontext.cache_id };
const gleich = (a, b) => String(a || '').trim().toLowerCase() === String(b || '').trim().toLowerCase();
let treffer = 0;
let vergleichbar = 0;
const unterschiede = [];
for (const [spalte, feld] of Object.entries(FELDER)) {
  out[`${spalte}_claude`] = String(dc[feld] ?? '');
  out[`${spalte}_ollama`] = String(dO[feld] ?? '');
  if (spalte === 'zusammenfassung') continue; // Freitext vergleichen wir nicht wörtlich
  vergleichbar++;
  if (gleich(dc[feld], dO[feld])) treffer++;
  else unterschiede.push(spalte);
}
out.modell_claude = c.modell || '';
out.modell_ollama = o.modell || '';
out.dauer_claude_s = c.dauer_s ?? null;
out.dauer_ollama_s = o.dauer_s ?? null;
out.uebereinstimmung = `${treffer}/${vergleichbar} Felder gleich`;
out.unterschiede = unterschiede.join(', ');
out.fehler = [c.ok ? '' : `Claude: ${c.fehler || 'keine Antwort'}`, o.ok ? '' : `Ollama: ${o.fehler || 'keine Antwort'}`].filter(Boolean).join(' | ');
out.verglichen_am = new Date().toISOString();
return [{ json: out }];

// Am "done"-Ausgang der Schleife kommen alle gespeicherten Vergleichszeilen an.
const zeilen = $input.all().map((i) => i.json);
const schnitt = (f) => {
  const w = zeilen.map((z) => z[f]).filter((x) => typeof x === 'number');
  return w.length ? Math.round((w.reduce((a, b) => a + b, 0) / w.length) * 10) / 10 : null;
};
const haeufig = {};
for (const z of zeilen) for (const u of String(z.unterschiede || '').split(', ').filter(Boolean)) haeufig[u] = (haeufig[u] || 0) + 1;
return [{ json: { verglichen: zeilen.length, sekunden_pro_seite_claude: schnitt('dauer_claude_s'), sekunden_pro_seite_ollama: schnitt('dauer_ollama_s'), unterschiede_nach_feld: haeufig } }];
